export function offerFor(p){return offers[p.id]||{title:p.title,audience:p.positioning?.audience||p.category,purpose:p.description,input:p.positioning?.inputHint||'Параметры задания',inputExample:p.example,output:p.positioning?.deliverable||p.delivery,unit:'записей',use:p.positioning?.nextStep||'Изучите результат в таблице.',limit:p.positioning?.limitations||'Доступность полей зависит от источника.',tag:p.category};}
export function offerPreview(p){const o=offerFor(p);if(!o.columns)return '';return `<div class="offer-preview"><div class="overline">ПРИМЕР ТАБЛИЦЫ · ВЫМЫШЛЕННЫЕ ДАННЫЕ</div><div class="sample-table"><table><caption>${esc(o.title)} — пример структуры, не результат реального сбора</caption><thead><tr>${o.columns.map(c=>`<th scope="col">${esc(c)}</th>`).join('')}</tr></thead><tbody>${o.rows.map(row=>`<tr>${row.map(c=>`<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div>`;}
export function offerCard(p,{favoriteControl=''}={}){const o=offerFor(p);return `<article class="offer-card"><div class="offer-card-top"><span class="overline">${esc(o.tag)}</span>${favoriteControl}</div><h3><a href="#product/${esc(p.id)}">${esc(o.title)}</a></h3><div class="offer-audience">${esc(o.audience)}</div><p>${esc(o.purpose)}</p><dl><dt>Вы указываете</dt><dd>${esc(o.input)}</dd><dt>Получаете</dt><dd>${esc(o.output)}</dd></dl><div class="offer-quantity">Один сбор · до ${p.maxItems} ${esc(o.unit)} · CSV / JSON</div><div class="offer-buy"><span><b>${new Intl.NumberFormat('ru-RU',{style:'currency',currency:'EUR'}).format(p.priceCents/100)}</b><small>демоцена за сбор</small></span><a class="primary" href="#product/${esc(p.id)}">Пример и параметры →</a></div></article>`;}

